/// A meta of a 400-character name (the pad's) is cut short with an ellipsis at half the
/// room between the row's name and its mark: the row 247 wide (the pane), its name from
/// 6 + 2 · 18 + 14 + 4 + 18 + 4 + 14 + 4 = 100, its mark 14 at 247 − 6 − 14 = 227, 4 before
/// it, so the room 100 to 223, the meta no wider than 61.5 and ending at 223; the name
/// keeps the rest.
#[test]
fn a_400_character_meta_is_cut_short_and_leaves_the_rows_name_room() {
    let f = fixture();
    let long = "R".repeat(400);
    let text = METAS.replace("\"name\": \"Raised\"", &format!("\"name\": \"{long}\""));
    let (mut h, _) = f.opened("metas.silico", &text);
    step_until(&mut h, "Cut's meta", |h| {
        shows(h, "Browser", "Cut") && row_texts(h, "Cut").len() == 2
    });
    let row = browser(&h).get_by_label("Cut").rect();
    let pane = browser(&h).rect();
    let galleys: Vec<_> = painted_in(&h, row)
        .into_iter()
        .filter_map(|shape| match shape {
            eframe::egui::Shape::Text(text) => Some(text),
            _ => None,
        })
        .collect();
    let shown: Vec<(String, eframe::egui::Rect)> = galleys
        .iter()
        .map(|text| {
            (
                text.galley.text().to_owned(),
                eframe::egui::Rect::from_min_size(text.pos, text.galley.size()),
            )
        })
        .collect();
    assert_eq!(shown.len(), 2, "{shown:?}");
    let (meta, at) = &shown[0];
    assert_eq!(meta, &long);
    // Cut with an ellipsis: its last glyph `…`, after `R`s.
    let glyphs: Vec<_> = galleys[0]
        .galley
        .rows
        .iter()
        .flat_map(|row| row.glyphs.iter())
        .collect();
    assert_eq!(glyphs.last().map(|glyph| glyph.chr), Some('…'));
    let r = glyphs.first().unwrap();
    assert_eq!(r.chr, 'R');
    let left = pane.left() + 100.0;
    let right = pane.left() + 223.0;
    assert!(at.width() <= 61.5 + 0.5, "{at:?}");
    // And as wide as half the room allows: within one `R` of it.
    assert!(
        at.width() > 61.5 - r.advance_width - 0.5,
        "{at:?}, an R {}",
        r.advance_width
    );
    assert!((at.right() - right).abs() <= 0.5, "{at:?}");
    assert!(at.left() >= left + 61.5 - 0.5, "{at:?}");
    let (name, at) = &shown[1];
    assert_eq!(name, "Cut");
    assert!((at.left() - left).abs() <= 0.5, "{at:?}");
    assert_eq!(never_waits::waits(), 0);
}

/// Two boxes of one name, each a body: the first 50 mm at the origin, the second 1 m, 2 m
/// along x.
const TWINS: &str = r#"{
  "silico": 1,
  "units": {"length": "mm", "resolution": "1nm"},
  "naming": 5,
  "features": [
    {"id": "k7f2qx3m", "type": "box", "v": 1, "name": "Cube", "position": [0, 0, 0], "length": 50, "width": 50, "height": 50},
    {"id": "a91cw0de", "type": "box", "v": 1, "name": "Cube", "position": [2000, 0, 0], "length": 1000, "width": 1000, "height": 1000}
  ]
}
"#;

#[test]
fn an_eye_hides_its_own_body_of_two_of_one_name_and_shows_closed() {
    let f = fixture();
    let (mut h, record) = f.drawn("twins.silico", TWINS);
    meshes_settled(&mut h);
    step_until(&mut h, "both eyes", |h| {
        browser(h).query_all_by_label("Hide Cube").count() == 2
    });
    // The second row's eye: that body alone hidden, its eye closed, the first's open.
    browser(&h)
        .query_all_by_label("Hide Cube")
        .nth(1)
        .unwrap()
        .click();
    step(&mut h);
    step(&mut h);
    assert_eq!(browser(&h).query_all_by_label("Hide Cube").count(), 1);
    assert_eq!(browser(&h).query_all_by_label("Show Cube").count(), 1);
    let eyes: Vec<String> = browser(&h)
        .query_all_by_role(Role::Button)
        .filter_map(|node| node.accesskit_node().label())
        .filter(|label| label.ends_with(" Cube"))
        .collect();
    assert_eq!(eyes, ["Hide Cube", "Show Cube"]);
    assert_eq!(
        h.state().tabs()[0]
            .overrides
            .iter()
            .map(|(what, kept)| (what.clone(), kept.shown))
            .collect::<Vec<_>>(),
        [(
            silico_app::tab::Hideable::Feature(
                silico_core::document::FeatureId::new("a91cw0de").unwrap()
            ),
            false
        )]
    );
    // The view draws the first body (the table's first) and not the second.
    assert_eq!(record.lock().unwrap().frames.last().unwrap().bodies, [1]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn h_hides_and_shows_the_selected_body_but_not_while_a_field_is_typed_in() {
    let f = fixture();
    let (mut h, record) = f.drawn("boxes.silico", TWO_BOXES);
    meshes_settled(&mut h);
    step_until(&mut h, "the browser's bodies", |h| {
        shows(h, "Browser", "Large")
    });
    browser(&h).get_by_label("Large").click();
    step_until(&mut h, "Large selected", |h| {
        toggled(&browser(h).get_by_label("Large")) == Some(true)
    });
    h.key_press(eframe::egui::Key::H);
    step(&mut h);
    step(&mut h);
    assert!(shows(&h, "Browser", "Show Large"));
    assert!(shows(&h, "Browser", "Hide Small"));
    assert_eq!(record.lock().unwrap().frames.last().unwrap().bodies, [1]);
    h.key_press(eframe::egui::Key::H);
    step(&mut h);
    step(&mut h);
    assert!(shows(&h, "Browser", "Hide Large"));
    assert_eq!(record.lock().unwrap().frames.last().unwrap().bodies, [1, 2]);
    // Typing in the Name field: the H is the field's, nothing hidden.
    name_field(&h).focus();
    step(&mut h);
    h.key_press(eframe::egui::Key::H);
    step(&mut h);
    step(&mut h);
    assert!(shows(&h, "Browser", "Hide Large"));
    assert!(h.state().tabs()[0].overrides.is_empty());
    assert_eq!(record.lock().unwrap().frames.last().unwrap().bodies, [1, 2]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn h_with_shift_or_alt_hides_nothing() {
    // H alone is Hide/Show (DESIGN.md, *Keyboard*); egui's own match would take Shift+H and
    // Alt+H for it too.
    let f = fixture();
    let (mut h, record) = f.drawn("boxes.silico", TWO_BOXES);
    meshes_settled(&mut h);
    step_until(&mut h, "the browser's bodies", |h| {
        shows(h, "Browser", "Large")
    });
    browser(&h).get_by_label("Large").click();
    step_until(&mut h, "Large selected", |h| {
        toggled(&browser(h).get_by_label("Large")) == Some(true)
    });
    for modifiers in [eframe::egui::Modifiers::SHIFT, eframe::egui::Modifiers::ALT] {
        h.key_press_modifiers(modifiers, eframe::egui::Key::H);
        step(&mut h);
        step(&mut h);
        assert!(shows(&h, "Browser", "Hide Large"), "{modifiers:?}");
        assert!(h.state().tabs()[0].overrides.is_empty(), "{modifiers:?}");
        assert_eq!(
            record.lock().unwrap().frames.last().unwrap().bodies,
            [1, 2],
            "{modifiers:?}"
        );
    }
    assert_eq!(never_waits::waits(), 0);
}

