#[test]
fn undo_and_redo_step_over_a_tangent_pair_and_a_relation_after_it_one_click_at_a_time() {
    // Tangent over the `on` (its add and its remove, one step, C5), then Horizontal on the
    // bottom: each Undo takes back one click, the pair whole, and each Redo gives one back.
    use silico_core::document::{Direction, Form};
    let f = fixture();
    let mut h = relating_sketch(&f);
    tangent_over_the_on(&f, &mut h);
    sketch_events(&f, &mut h, &clicked(30.0, 10.0));
    relate_button(&mut h, "Horizontal");
    settled(&mut h);
    let forms = |h: &AppHarness| -> Vec<Form> {
        sketch_of_text(&f, h, "s0000001")
            .constraints
            .into_iter()
            .map(|c| c.form)
            .collect()
    };
    let tangent = Form::TangentOn {
        a: element_ref("nd000001"),
        at: element_ref("pd000002"),
        b: element_ref("cc000001"),
        direction: Direction::Same,
    };
    let replaced = Form::On {
        point: element_ref("pd000002"),
        curve: element_ref("cc000001"),
    };
    let horizontal = Form::Horizontal {
        line: element_ref("na000001"),
    };
    let holds = |h: &AppHarness, expected: [(&Form, bool); 3]| {
        let now = forms(h);
        for (form, there) in expected {
            assert_eq!(now.contains(form), there, "{form:?} in {now:?}");
        }
    };
    holds(
        &h,
        [(&tangent, true), (&replaced, false), (&horizontal, true)],
    );
    // Undo: the Horizontal alone.
    undo_by_key(&mut h);
    holds(
        &h,
        [(&tangent, true), (&replaced, false), (&horizontal, false)],
    );
    // Undo: the pair, whole.
    undo_by_key(&mut h);
    assert_eq!(text_of(&f.sessions, &h), RELATING);
    // Redo: the pair, whole.
    redo_by_key(&mut h);
    holds(
        &h,
        [(&tangent, true), (&replaced, false), (&horizontal, false)],
    );
    // Redo: the Horizontal.
    redo_by_key(&mut h);
    holds(
        &h,
        [(&tangent, true), (&replaced, false), (&horizontal, true)],
    );
    assert_eq!(h.state().tabs()[0].message, None);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn no_other_sketch_mode_opens_while_a_finished_ones_click_waits_and_its_cancel_keeps_that_edit() {
    // Sketch mode A: Horizontal and Vertical, the Horizontal's edit held unanswered behind
    // another command, so the Vertical is still a click to plan; then Finish, A kept for it.
    // Edit Sketch doesn't open another sketch mode while A's close waits behind that click,
    // so a Cancel never meets another mode's click. Once A has settled, sketch mode B opens
    // after A's edits, and its Cancel, back to where B opened, keeps them.
    use silico_core::command::CheckModel;
    use silico_core::document::{ElementKind, Form};
    use silico_core::sketch_tools::RelationTool;
    let f = fixture();
    let mut h = relating_sketch(&f);
    let id = h.state().tabs()[0].id;
    f.sketches.hold();
    let check = f.sessions.check(&id, CheckModel::Current { fresh: true });
    assert!(f.sketches.wait_held(WAIT));
    {
        let sessions = Arc::clone(&f.sessions);
        let _marked = never_waits::marked();
        select_member(&mut h, "na000001", ElementKind::Line);
        h.state_mut().tabs_mut()[0].sketch_relate(&sessions, RelationTool::Horizontal);
        select_member(&mut h, "na000002", ElementKind::Line);
        let tab = &mut h.state_mut().tabs_mut()[0];
        tab.sketch_relate(&sessions, RelationTool::Vertical);
        tab.finish_sketch(&sessions, true);
    }
    assert_eq!(h.state().tabs()[0].leaving(), 1);
    {
        let sessions = Arc::clone(&f.sessions);
        let _marked = never_waits::marked();
        let tab = &mut h.state_mut().tabs_mut()[0];
        assert!(!tab.can_sketch(), "a sketch mode's close waits");
        tab.edit_sketch(&sessions, &sketch_id("s0000001"));
        assert!(tab.sketch.is_none(), "no sketch mode B");
    }
    f.sketches.release();
    check.wait();
    settled(&mut h);
    let forms = |h: &AppHarness| -> Vec<Form> {
        sketch_of_text(&f, h, "s0000001")
            .constraints
            .into_iter()
            .map(|c| c.form)
            .collect()
    };
    let kept = [
        Form::Horizontal {
            line: element_ref("na000001"),
        },
        Form::Vertical {
            line: element_ref("na000002"),
        },
    ];
    for form in &kept {
        assert!(forms(&h).contains(form), "{form:?} in {:?}", forms(&h));
    }
    assert_eq!(h.state().tabs()[0].leaving(), 0);
    // B, opened now, and Cancelled: A's edits stay.
    {
        let sessions = Arc::clone(&f.sessions);
        let _marked = never_waits::marked();
        let tab = &mut h.state_mut().tabs_mut()[0];
        tab.edit_sketch(&sessions, &sketch_id("s0000001"));
        assert!(tab.sketch.is_some(), "sketch mode B open");
        tab.finish_sketch(&sessions, false);
    }
    settled(&mut h);
    for form in &kept {
        assert!(forms(&h).contains(form), "{form:?} in {:?}", forms(&h));
    }
    assert_eq!(h.state().tabs()[0].message, None);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn a_click_while_the_read_is_an_older_models_refusal_waits_for_the_next_read() {
    // Create Sketch, its revision's rebuild held at the new sketch's solve: sketch mode's
    // read, of the published model from before the sketch was added, refuses it. Fix pressed
    // then, with nothing selected, waits (the rebuild runs, so a read is coming); once the
    // sketch is read, Fix says the prototype's words, and no "wasn't added".
    use silico_core::sketch_tools::RelationTool;
    let f = fixture();
    let (mut h, _) = f.opened("relating.silico", RELATING);
    step_until(&mut h, "its sketch", |h| shows(h, "Browser", "Relate"));
    settled(&mut h);
    f.sketches.hold();
    create_sketch(&mut h, "XY plane");
    step_until(
        &mut h,
        "the older model's refusal read, the new revision rebuilding",
        |h| {
            let tab = &h.state().tabs()[0];
            f.sketches.wait_held(Duration::ZERO)
                && tab
                    .sketch
                    .as_ref()
                    .and_then(|mode| mode.read.as_ref())
                    .is_some_and(|read| {
                        read.result.is_err() && read.model.is_some_and(|model| model < tab.revision)
                    })
        },
    );
    {
        let sessions = Arc::clone(&f.sessions);
        let _marked = never_waits::marked();
        h.state_mut().tabs_mut()[0].sketch_relate(&sessions, RelationTool::Fix);
    }
    let tab = &h.state().tabs()[0];
    assert_eq!(tab.message, None, "let go");
    assert!(tab.unsettled(), "the click waits");
    f.sketches.release();
    step_until(&mut h, "Fix planned on the sketch's read", |h| {
        toast_said(h).is_some_and(|(text, _)| {
            text == "Select the curves or points first; the relation applies to them."
        })
    });
    settled(&mut h);
    assert_eq!(h.state().tabs()[0].message, None);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn delete_during_a_drag_waits_for_its_end_then_goes_against_its_revision_and_both_land() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    // The bottom, na000001, selected; then the corner pa000003 dragged.
    sketch_events(&f, &mut h, &clicked(30.0, 10.0));
    assert_eq!(
        sketch_mode(&h)
            .unwrap()
            .selected_ids()
            .iter()
            .map(|i| i.as_str().to_owned())
            .collect::<Vec<_>>(),
        ["na000001"]
    );
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    drag_frames(&mut h, 1);
    // A move held in the worker, and Delete pressed: nothing sent while the drag lasts.
    f.sketches.hold();
    sketch_events(&f, &mut h, &moved(54.0, 34.0));
    assert!(f.sketches.wait_held(WAIT));
    h.key_press(eframe::egui::Key::Delete);
    step(&mut h);
    sketch_events(&f, &mut h, &[pointer(Release, 54.0, 34.0)]);
    for _ in 0..10 {
        step(&mut h);
    }
    assert_eq!(drag_sends(&h, "sketch_remove"), 0);
    assert_eq!(drag_sends(&h, "drag_end"), 1);
    // The worker let go: the drag ends, then the removal goes, against the drag's revision.
    f.sketches.release();
    settled(&mut h);
    let sent = &h.state().tabs()[0].sent;
    let end = sent
        .iter()
        .position(|s| *s == Sent::SketchEdit("drag_end"))
        .unwrap();
    let remove = sent
        .iter()
        .position(|s| *s == Sent::SketchEdit("sketch_remove"))
        .unwrap();
    assert!(end < remove);
    assert_eq!(h.state().tabs()[0].message, None);
    let sketch = sketch_of_text(&f, &h, "s0000001");
    assert!(sketch.lines.iter().all(|l| l.id.as_str() != "na000001"));
    let corner = sketch
        .points
        .iter()
        .find(|p| p.id.as_str() == "pa000003")
        .unwrap();
    assert!((corner.x.mm() - 54.05).abs() < 1e-9 && (corner.y.mm() - 34.03).abs() < 1e-9);
    assert_eq!(never_waits::waits(), 0);
}

/// [`BOXED`] with the bottom's length, 40.
const BOXED_LENGTH: &str = r#"{
  "silico": 1,
  "units": {"length": "mm", "resolution": "1nm"},
  "naming": 5,
  "features": [
    {"id": "s0000001", "type": "sketch", "v": 1, "name": "Box", "plane": "xy", "points": [{"id": "pa000001", "x": 10, "y": 10, "construction": false}, {"id": "pa000002", "x": 50, "y": 10, "construction": false}, {"id": "pa000003", "x": 50, "y": 30, "construction": false}, {"id": "pa000004", "x": 10, "y": 30, "construction": false}], "lines": [{"id": "na000001", "from": "pa000001", "to": "pa000002", "construction": false}, {"id": "na000002", "from": "pa000002", "to": "pa000003", "construction": false}, {"id": "na000003", "from": "pa000003", "to": "pa000004", "construction": false}, {"id": "na000004", "from": "pa000004", "to": "pa000001", "construction": false}], "circles": [], "arcs": [], "constraints": [{"id": "ka000001", "type": "horizontal", "line": "na000001"}, {"id": "ka000002", "type": "vertical", "line": "na000002"}, {"id": "ka000003", "type": "horizontal", "line": "na000003"}, {"id": "ka000004", "type": "vertical", "line": "na000004"}, {"id": "ka000005", "type": "length", "line": "na000001", "value": 40, "driving": true}]}
  ]
}
"#;

/// As [`counting`], but a length of 99 mm repeats the others (redundant), which leaves the
/// sketch's constraints agreeing, so a drag may begin; and one of 98 mm disagrees with them
/// (in conflict).
fn counting_redundant_99(f: &Fixture) {
    use silico_protocol::{Solved, SolverConstraint, Tag};
    f.sketches.answer(|system| {
        let sent = FakeSketches::as_sent(system);
        let equations = system
            .constraints
            .iter()
            .filter(|c| c.tag().is_some())
            .count();
        let dofs = system.unknowns.len() as i32 - equations as i32;
        let redundant: Vec<Tag> = system
            .constraints
            .iter()
            .filter_map(|c| match c {
                SolverConstraint::Distance { tag, value, .. }
                    if system.values.get(value.0 as usize) == Some(&99.0) =>
                {
                    Some(*tag)
                }
                _ => None,
            })
            .collect();
        let conflicting: Vec<Tag> = system
            .constraints
            .iter()
            .filter_map(|c| match c {
                SolverConstraint::Distance { tag, value, .. }
                    if system.values.get(value.0 as usize) == Some(&98.0) =>
                {
                    Some(*tag)
                }
                _ => None,
            })
            .collect();
        Ok(Solved {
            dofs,
            redundant,
            conflicting,
            free: if dofs > 0 {
                system.unknowns.clone()
            } else {
                Vec::new()
            },
            ..sent
        })
    });
}

/// The over-define prompt up ([`over_define_offered`]), the navigation bar's `tool` chosen
/// first, if any: Esc takes a held drag first, then the prompt, each before the prototype's
/// `escChain` gives it to the tool (`Tab::escape_first`). A drag of the free far corner, held
/// while the prompt is up, ends from its begin, the prompt staying and nothing undone; the
/// next Esc is the prompt's Cancel, the edit undone, the text as it was. The tool stays
/// through each; with one chosen, the bottom's dimension's Modify box then closes, its value
/// as it was, the tool still staying, and the Esc after lets it go, sketch mode still open.
fn esc_takes_a_held_drag_then_the_prompts_cancel(tool: Option<silico_app::viewport::Navigation>) {
    use eframe::egui::Key;
    use silico_app::sketch::PointerAction::{Move, Press};
    let f = fixture();
    // The bottom's length set to 99, which repeats the others: the three offered.
    let (mut h, text) = over_define_offered(&f, tool);
    // The far corner, still free, dragged while the prompt is up.
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    drag_frames(&mut h, 1);
    // The first Esc ends the drag from its begin; the prompt stays.
    h.key_press(Key::Escape);
    step(&mut h);
    settled(&mut h);
    assert_eq!(drag_sends(&h, "drag_end"), 1);
    assert!(sketch_mode(&h).unwrap().offer().is_some());
    assert!(!h.state().tabs()[0].sent.contains(&Sent::Undo(None)));
    assert_eq!(view(&h).tool, tool);
    // The second is the prompt's Cancel: the edit undone, the text as it was.
    h.key_press(Key::Escape);
    step(&mut h);
    settled(&mut h);
    assert!(sketch_mode(&h).unwrap().offer().is_none());
    assert_eq!(h.state().tabs()[0].sent.last(), Some(&Sent::Undo(None)));
    assert_eq!(text_of(&f.sessions, &h), text);
    assert_eq!(view(&h).tool, tool);
    if tool.is_some() {
        // The Modify box, the sketch read again, 33 typed into it: Esc closes it, its value
        // as it was, nothing sent.
        sketch_read(&mut h);
        open_modify_box(&f, &mut h);
        modify_dimension(
            &f,
            &mut h,
            silico_app::sketch::dimension::ModifyAction::Typed("33".to_owned()),
        );
        let typed = sketch_mode(&h)
            .unwrap()
            .edit_box
            .as_ref()
            .map(|edit| edit.text.clone());
        assert_eq!(typed.as_deref(), Some("33"));
        let sent = h.state().tabs()[0].sent.clone();
        h.key_press(Key::Escape);
        step(&mut h);
        settled(&mut h);
        assert!(sketch_mode(&h).unwrap().edit_box.is_none());
        assert_eq!(h.state().tabs()[0].sent, sent);
        assert_eq!(text_of(&f.sessions, &h), text);
        assert_eq!(view(&h).tool, tool);
        // Then the bar's tool.
        h.key_press(Key::Escape);
        step(&mut h);
        assert_eq!(view(&h).tool, None);
        assert!(sketch_mode(&h).is_some());
    }
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn esc_takes_a_held_drag_before_the_over_define_prompt_and_then_the_prompts_cancel() {
    esc_takes_a_held_drag_then_the_prompts_cancel(None);
}

#[test]
fn a_press_on_a_read_older_than_the_sessions_state_begins_no_drag() {
    use silico_app::sketch::PointerAction::{Move, Press};
    use silico_core::document::FeatureId;
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    settled(&mut h);
    // Another client renames the sketch; the tab polled once, which learns the new
    // revision and asks its read, still to be taken: the read drawn is the one before.
    let session = h.state().tabs()[0].id;
    let revision = f.sessions.status(&session).session.unwrap().revision;
    let renamed = f
        .sessions
        .set_field(
            &session,
            revision,
            FeatureId::new("s0000001").unwrap(),
            "name".to_owned(),
            json::read(br#""Renamed""#).unwrap(),
        )
        .wait();
    assert!(renamed.result.is_ok(), "{:?}", renamed.result);
    {
        let sessions = Arc::clone(&f.sessions);
        let _marked = never_waits::marked();
        h.state_mut().tabs_mut()[0].poll(&sessions);
    }
    assert!(h.state().tabs()[0].revision > revision);
    assert_eq!(
        sketch_mode(&h).unwrap().read.as_ref().and_then(|r| r.model),
        Some(revision)
    );
    // A press and a move on it: no drag begun, the grab let go.
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    for _ in 0..5 {
        step(&mut h);
    }
    assert_eq!(drag_sends(&h, "drag_begin"), 0);
    assert!(the_drag(&h).is_none());
    // Once the read of the new revision is taken, a press drags again.
    sketch_events(
        &f,
        &mut h,
        &[pointer(
            silico_app::sketch::PointerAction::Release,
            52.0,
            32.0,
        )],
    );
    step_until(&mut h, "the new read", |h| {
        sketch_mode(h)
            .and_then(|m| m.read.as_ref())
            .and_then(|r| r.model)
            .is_some_and(|model| model > revision)
    });
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    assert_eq!(drag_sends(&h, "drag_begin"), 1);
    h.key_press(eframe::egui::Key::Escape);
    step(&mut h);
    settled(&mut h);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn esc_while_the_begin_is_unanswered_ends_the_drag_once_it_answers() {
    use silico_app::sketch::PointerAction::{Move, Press};
    use silico_core::command::CheckModel;
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    let text = text_of(&f.sessions, &h);
    // Another client's fresh check, its rebuild's solve held, ahead in the session's queue.
    f.sketches.hold();
    let session = h.state().tabs()[0].id;
    let check = f
        .sessions
        .check(&session, CheckModel::Current { fresh: true });
    assert!(f.sketches.wait_held(WAIT));
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    assert_eq!(drag_sends(&h, "drag_begin"), 1);
    // Esc with the begin queued behind it: ended, its end to go once the begin answers.
    h.key_press(eframe::egui::Key::Escape);
    for _ in 0..5 {
        step(&mut h);
    }
    assert_eq!(drag_sends(&h, "drag_end"), 0);
    assert!(the_drag(&h).is_some_and(|d| !d.held() && d.in_flight()));
    f.sketches.release();
    assert!(check.wait().result.is_ok());
    settled(&mut h);
    step_until(&mut h, "the drag over", |h| the_drag(h).is_none());
    assert_eq!(drag_sends(&h, "drag_end"), 1);
    assert_eq!(status_drag(&f, &h), None);
    assert_eq!(text_of(&f.sessions, &h), text);
    assert_eq!(never_waits::waits(), 0);
}

/// A circle of radius 10 about (30, 30), free.
const CIRCLED: &str = r#"{
  "silico": 1,
  "units": {"length": "mm", "resolution": "1nm"},
  "naming": 5,
  "features": [
    {"id": "s0000001", "type": "sketch", "v": 1, "name": "Round", "plane": "xy", "points": [{"id": "pc000001", "x": 30, "y": 30, "construction": false}], "lines": [], "circles": [{"id": "ca000001", "center": "pc000001", "radius": 10, "construction": false}], "arcs": [], "constraints": []}
  ]
}
"#;

#[test]
fn a_line_dragged_by_its_edge_moves_whole_and_a_circles_edge_passes_the_cores_press_check() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    use silico_core::command::DragGrab;
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    // The bottom, na000001, pressed at (30, 10.3), 0.3 mm off it: grabbed at (30, 10), on
    // it exactly, which the core's press check takes.
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 30.0, 10.3), pointer(Move, 30.0, 15.0)],
    );
    assert_eq!(
        the_drag(&h).unwrap().grab,
        DragGrab::Edge {
            curve: silico_core::document::ElementId::new("na000001").unwrap(),
            press: [30.0, 10.0]
        }
    );
    drag_frames(&mut h, 1);
    // Its two ends by the cursor's offset from the press, (0, 5), each nudged a thousandth
    // of where it began, as the fake answers: (10.01, 15.01) and (50.05, 15.01).
    let near = |a: [f64; 2], b: [f64; 2]| (a[0] - b[0]).abs() < 1e-9 && (a[1] - b[1]).abs() < 1e-9;
    assert!(near(shown_at(&h, "pa000001").unwrap(), [10.01, 15.01]));
    assert!(near(shown_at(&h, "pa000002").unwrap(), [50.05, 15.01]));
    sketch_events(&f, &mut h, &[pointer(Release, 30.0, 15.0)]);
    settled(&mut h);
    assert_eq!(h.state().tabs()[0].message, None);
    let sketch = sketch_of_text(&f, &h, "s0000001");
    let at = |id: &str| {
        let p = sketch.points.iter().find(|p| p.id.as_str() == id).unwrap();
        [p.x.mm(), p.y.mm()]
    };
    assert!(near(at("pa000001"), [10.01, 15.01]));
    assert!(near(at("pa000002"), [50.05, 15.01]));
    // A circle's edge: pressed on it at (40, 30), dragged out, begun and ended with no
    // refusal (the fake's frame keeps the radius).
    let f = fixture();
    counting(&f);
    let (mut h, _) = f.opened("circled.silico", CIRCLED);
    step_until(&mut h, "its sketch", |h| shows(h, "Browser", "Round"));
    double_click(&mut h, "Browser", "Round");
    step_until(&mut h, "sketch mode", |h| sketch_mode(h).is_some());
    sketch_read(&mut h);
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 40.0, 30.0), pointer(Move, 45.0, 30.0)],
    );
    assert_eq!(
        the_drag(&h).unwrap().grab,
        DragGrab::Edge {
            curve: silico_core::document::ElementId::new("ca000001").unwrap(),
            press: [40.0, 30.0]
        }
    );
    drag_frames(&mut h, 1);
    sketch_events(&f, &mut h, &[pointer(Release, 45.0, 30.0)]);
    settled(&mut h);
    step_until(&mut h, "the drag over", |h| the_drag(h).is_none());
    assert_eq!(h.state().tabs()[0].message, None);
    assert_eq!(drag_sends(&h, "drag_end"), 1);
    assert_eq!(status_drag(&f, &h), None);
    assert_eq!(never_waits::waits(), 0);
}

