#[test]
fn a_press_moved_while_an_edit_is_under_way_begins_no_drag() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    // The bottom, na000001, selected.
    sketch_events(&f, &mut h, &clicked(30.0, 10.0));
    settled(&mut h);
    // The session's queue held behind a fresh check, whose solve is held; then Delete: its
    // removal sent, waiting behind it, so the tab's edit is under way.
    f.sketches.hold();
    let id = h.state().tabs()[0].id;
    let check = f.sessions.check(&id, CheckModel::Current { fresh: true });
    assert!(f.sketches.wait_held(WAIT));
    h.key_press(Key::Delete);
    step(&mut h);
    assert_eq!(drag_sends(&h, "sketch_remove"), 1);
    assert!(h.state().tabs()[0].unsettled());
    // Pressed on the corner pa000003, (50, 30), and moved to (52, 32), past the threshold:
    // but its begin goes only once nothing of the tab's is under way (section 9,
    // *Dragging*), so none is sent while the removal waits.
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    for _ in 0..5 {
        step(&mut h);
    }
    assert_eq!(drag_sends(&h, "drag_begin"), 0);
    // Let go: the removal lands, a state after the read the press was on, so the press
    // drags nothing; released, nothing more is sent.
    f.sketches.release();
    assert!(check.wait().result.is_ok());
    settled(&mut h);
    sketch_events(&f, &mut h, &[pointer(Release, 52.0, 32.0)]);
    settled(&mut h);
    assert_eq!(drag_sends(&h, "drag_begin"), 0);
    assert!(the_drag(&h).is_none());
    let sketch = sketch_of_text(&f, &h, "s0000001");
    assert!(sketch.lines.iter().all(|l| l.id.as_str() != "na000001"));
    let corner = sketch
        .points
        .iter()
        .find(|p| p.id.as_str() == "pa000003")
        .unwrap();
    assert_eq!([corner.x.mm(), corner.y.mm()], [50.0, 30.0]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn a_drag_ended_from_its_begin_after_an_undo_in_sketch_mode_keeps_what_was_undone_to_redo() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    let text = text_of(&f.sessions, &h);
    let pressed_on_newest = |f: &Fixture, h: &mut AppHarness, to: [f64; 2]| {
        // Pressed on a read of the session's state, as a drag begins only from one.
        step_until(h, "the read of the session's revision", |h| {
            let tab = &h.state().tabs()[0];
            sketch_mode(h)
                .and_then(|mode| mode.read.as_ref())
                .and_then(|read| read.model)
                == Some(tab.revision)
        });
        sketch_events(
            f,
            h,
            &[pointer(Press, 50.0, 30.0), pointer(Move, to[0], to[1])],
        );
        step_until(h, "the frame", |h| {
            the_drag(h).is_some_and(|d| d.frames >= 1)
        });
    };
    let undone = |h: &AppHarness| sketch_mode(h).unwrap().undone;
    // A drag's edit, then undone by Ctrl+Z: one of sketch mode's own edits undone.
    pressed_on_newest(&f, &mut h, [52.0, 32.0]);
    sketch_events(&f, &mut h, &[pointer(Release, 52.0, 32.0)]);
    settled(&mut h);
    step_until(&mut h, "the drag over", |h| the_drag(h).is_none());
    let dragged = text_of(&f.sessions, &h);
    assert_ne!(dragged, text);
    step(&mut h);
    h.key_press_modifiers(Modifiers::COMMAND, Key::Z);
    step(&mut h);
    settled(&mut h);
    assert_eq!(undone(&h), 1);
    assert_eq!(text_of(&f.sessions, &h), text);
    // A second drag, ended by Esc from its begin state: it changed nothing, so it's no new
    // edit, and what was undone stays sketch mode's to redo.
    pressed_on_newest(&f, &mut h, [56.0, 36.0]);
    h.key_press(Key::Escape);
    step(&mut h);
    settled(&mut h);
    step_until(&mut h, "the drag over", |h| the_drag(h).is_none());
    assert_eq!(drag_sends(&h, "drag_end"), 2);
    assert_eq!(text_of(&f.sessions, &h), text);
    assert_eq!(undone(&h), 1);
    // Ctrl+Y gives the first drag's edit back.
    step(&mut h);
    h.key_press_modifiers(Modifiers::COMMAND, Key::Y);
    step(&mut h);
    settled(&mut h);
    assert_eq!(text_of(&f.sessions, &h), dragged);
    assert_eq!(undone(&h), 0);
    assert_eq!(never_waits::waits(), 0);
}

/// [`BOXED`] with a pad of its rectangle, whose rebuild asks the kernel.
fn boxed_padded() -> String {
    let pad = r#"    {"id": "p0000001", "type": "pad", "v": 1, "name": "Pad", "sketch": "s0000001", "extent": {"type": "one_side", "length": 10, "reversed": false}}"#;
    BOXED.replace("]}\n  ]\n}", &format!("]}},\n{pad}\n  ]\n}}"))
}

#[test]
fn a_drags_changed_end_is_drawn_from_its_last_frame_until_a_read_of_its_edit() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    let f = fixture();
    counting(&f);
    let text = boxed_padded();
    let (mut h, _) = f.opened("boxed.silico", &text);
    step_until(&mut h, "its sketch", |h| shows(h, "Browser", "Box"));
    double_click(&mut h, "Browser", "Box");
    step_until(&mut h, "sketch mode", |h| sketch_mode(h).is_some());
    sketch_read(&mut h);
    settled(&mut h);
    step_until(&mut h, "the read of the published revision", |h| {
        let tab = &h.state().tabs()[0];
        tab.published == Some(tab.revision)
            && sketch_mode(h)
                .and_then(|mode| mode.read.as_ref())
                .and_then(|read| read.model)
                == Some(tab.revision)
    });
    let before = h.state().tabs()[0].revision;
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    drag_frames(&mut h, 1);
    // Every kernel request held from now on: the pad's rebuild of the drag's edit waits,
    // so the model it makes isn't published, and no read of it comes.
    let hold = f.kernel.hold(|_| true);
    sketch_events(&f, &mut h, &[pointer(Release, 52.0, 32.0)]);
    step_until(&mut h, "the end answered", |h| {
        the_drag(h).is_none_or(|d| !d.in_flight())
    });
    // The end's edit is made inside the drag's transaction, where an edit starts no
    // rebuild until a read of the current model asks for one: the app's read of the new
    // revision, sent in the frame after it sees it, which may come after the end's answer.
    // So frames are stepped until the edit's rebuild runs, held at its first request.
    step_until(&mut h, "the edit's rebuild under way", |_| {
        f.kernel.wait_running(1, Duration::ZERO)
    });
    for _ in 0..10 {
        step(&mut h);
    }
    // Its edit made a new revision, read only at the one before: the drag is kept, and
    // what's drawn is its last frame, the corner at (52.05, 32.03) (the fake's).
    assert!(h.state().tabs()[0].revision > before);
    assert_eq!(
        sketch_mode(&h)
            .and_then(|mode| mode.read.as_ref())
            .and_then(|read| read.model),
        Some(before)
    );
    let shown = shown_at(&h, "pa000003").unwrap();
    assert!((shown[0] - 52.05).abs() < 1e-9 && (shown[1] - 32.03).abs() < 1e-9);
    // Let go: the read of the edit comes, and the drag is over, the read drawing it.
    hold.release();
    step_until(&mut h, "the drag over", |h| the_drag(h).is_none());
    let read = sketch_mode(&h).and_then(|mode| mode.read.as_ref()).unwrap();
    assert_eq!(read.model, Some(h.state().tabs()[0].revision));
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn delete_waiting_behind_a_drag_is_sent_in_the_frame_its_end_is_answered() {
    use silico_app::sketch::PointerAction::{Move, Press, Release};
    let f = fixture();
    counting(&f);
    let mut h = boxed_sketch(&f);
    // One pass a frame, so each step polls the tab once.
    h.ctx
        .options_mut(|options| options.max_passes = std::num::NonZeroUsize::MIN);
    // The bottom, na000001, selected; then the corner pa000003 dragged, and Delete pressed:
    // nothing sent while the drag lasts.
    sketch_events(&f, &mut h, &clicked(30.0, 10.0));
    sketch_events(
        &f,
        &mut h,
        &[pointer(Press, 50.0, 30.0), pointer(Move, 52.0, 32.0)],
    );
    drag_frames(&mut h, 1);
    h.key_press(Key::Delete);
    step(&mut h);
    assert_eq!(drag_sends(&h, "sketch_remove"), 0);
    // The release, given to sketch mode with no frame of the app's after it; then a frame at
    // a time until one has taken the end's answer: that one sends the removal behind it.
    {
        let _marked = never_waits::marked();
        let ctx = eframe::egui::Context::default();
        let sessions = Arc::clone(&f.sessions);
        let tab = &mut h.state_mut().tabs_mut()[0];
        let events = [pointer(Release, 52.0, 32.0)];
        let mut output = ctx.run_ui(eframe::egui::RawInput::default(), |ui| {
            let painter = ui.painter().clone();
            let input = silico_app::sketch::FrameInput {
                events: &events,
                pointer: events.last().map(|event| event.at),
                project: &to_screen,
                to_plane: &to_sketch,
            };
            tab.sketch_frame(&sessions, &painter, &input);
        });
        output.textures_delta.clear();
    }
    assert_eq!(drag_sends(&h, "drag_end"), 1);
    let deadline = Instant::now() + WAIT;
    while the_drag(&h).is_some_and(|d| d.in_flight()) {
        assert_eq!(drag_sends(&h, "sketch_remove"), 0);
        assert!(Instant::now() < deadline, "the end never answered");
        std::thread::sleep(Duration::from_millis(1));
        step(&mut h);
    }
    assert_eq!(drag_sends(&h, "sketch_remove"), 1);
    settled(&mut h);
    let sketch = sketch_of_text(&f, &h, "s0000001");
    assert!(sketch.lines.iter().all(|l| l.id.as_str() != "na000001"));
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn an_undo_refused_as_a_conflict_says_the_cores_refusal_not_the_prompts_overtaken() {
    let f = fixture();
    let (mut h, _) = f.opened("example.silico", EXAMPLE);
    step_until(&mut h, "its features", |h| shows(h, "Timeline", "Pin"));
    select(&mut h, "Pin");
    type_name(&mut h, "K");
    step_until(&mut h, "Undo offered", |h| {
        h.state().tabs()[0].edits.idle() && offered(h, "Undo")
    });
    let mine = h.state().tabs()[0].revision;
    let text = text_of(&f.sessions, &h);
    // The session's queue held; another client's edit queued first, then Ctrl+Z, made
    // against the revision the tab is at, which the other's moves the session past.
    let (hold, check) = hold_queue(&f, &h, 0);
    let id = h.state().tabs()[0].id;
    let theirs = f.sessions.replace_text(
        &id,
        mine,
        text.replace(r#""name": "Hole""#, r#""name": "Theirs""#),
    );
    h.key_press_modifiers(Modifiers::COMMAND, Key::Z);
    step(&mut h);
    assert!(
        h.state().tabs()[0]
            .sent
            .iter()
            .any(|sent| matches!(sent, Sent::Undo(_)))
    );
    hold.release();
    check.wait();
    assert!(theirs.wait().result.is_ok());
    step_until(&mut h, "the refusal said", |h| {
        h.state().tabs()[0].message.is_some()
    });
    // Said as any refusal is, worked from the core's wording of a stale undo: not the
    // over-define prompt's word, which is for its own choice alone.
    let (made, at) = (mine.number(), mine.number() + 1);
    assert_eq!(
        h.state().tabs()[0].message.as_deref(),
        Some(
            format!(
                "the undo was made against revision {made}, and the session is at revision {at} (read the document again (text or outline), then undo against revision {at})"
            )
            .as_str()
        )
    );
    assert_eq!(never_waits::waits(), 0);
}

// ---- Untitled parts (docs/design/m5.0-app.md §4, New; open item 30, overturned) ----
//
// New opens a part with no file (`open_untitled`), named "Untitled", "Untitled 2", ...; its
// first save is a Save As through the Save panel (the stand-in, as above), and with no
// native dialogs, or one that won't open, through the typed Save As. Expected names and
// paths are written here by hand; files' contents are the session's text, read from the
// core, and the features' names in them.

/// The part `part`, shown, in sketch mode on a new sketch, as a part is begun sketch-first
/// (the app makes no primitive: Trevin's decision of 2026-11-09): CREATE's Create Sketch,
/// once the part's timeline is read, on the XY plane, its sketch added and read.
fn begin_sketch_on_xy(h: &mut AppHarness, part: &str) {
    begin_sketch_on(h, part, "XY plane");
}

/// Finish Sketch (⌘↵) in the part `part`, shown, which keeps its sketch (one holding
/// something): sketch mode closed, and the part's edits held, unsaved, its tab marked.
fn finish_sketch_unsaved(h: &mut AppHarness, part: &str) {
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::Enter);
    let marked = format!("{part} *");
    step_until(h, "sketch mode closed, unsaved", |h| {
        let tab = tab_named(h, part);
        tab.sketch.is_none() && tab.edits.idle() && tab.unsaved() && anywhere(h, &marked)
    });
}

/// A sketch added to the part `part`, shown: [`begin_sketch_on_xy`], a point placed at
/// (10, 10), then Finish Sketch, which keeps it, holding the point, as "Sketch1" (one
/// holding nothing it would discard).
fn add_sketch(h: &mut AppHarness, part: &str) {
    begin_sketch_on_xy(h, part);
    place_point_in(h, part, 10.0, 10.0);
    finish_sketch_unsaved(h, part);
}

/// The part `part`, shown, given a sketch with a profile: [`begin_sketch_on_xy`], a corner
/// rectangle from the origin to (40, 20) drawn with R (its events given to the tab's sketch
/// mode as [`sketch_events`] gives them), and Finish Sketch, which keeps it as "Sketch1".
fn add_rectangle(f: &Fixture, h: &mut AppHarness, part: &str) {
    let at = h
        .state()
        .tabs()
        .iter()
        .position(|tab| tab.name() == part)
        .unwrap();
    begin_sketch_on_xy(h, part);
    h.key_press(eframe::egui::Key::R);
    step(h);
    sketch_events_at(f, h, at, &dragged([0.0, 0.0], [40.0, 20.0]));
    step_until(h, "its four lines read", |h| {
        let tab = tab_named(h, part);
        tab.edits.idle()
            && tab
                .sketch
                .as_ref()
                .and_then(|mode| mode.drawable())
                .is_some_and(|read| read.members.lines.len() == 4)
    });
    finish_sketch_unsaved(h, part);
}

/// A solid made sketch-first in the part `part`, shown: [`add_rectangle`], then CREATE's
/// Pad of its sketch, chosen in the browser, its add answered and OK'd. The part then holds
/// "Sketch1" and "Pad", unsaved, its tab marked, and the kernel has built the pad's prism.
fn add_pad(f: &Fixture, h: &mut AppHarness, part: &str) {
    add_rectangle(f, h, part);
    step_until(h, "its sketch", |h| shows(h, "Browser", "Sketch1"));
    h.get_by_role_and_label(Role::Pane, "Browser")
        .get_by_label("Sketch1")
        .click();
    step(h);
    create(h, "Pad");
    step_until(h, "its add answered", |h| {
        tab_named(h, part)
            .dialog
            .as_ref()
            .is_some_and(|dialog| dialog.feature.is_some() && !dialog.adding)
    });
    step_until(h, "OK on", ok_enabled);
    dialog(h).get_by_role_and_label(Role::Button, "OK").click();
    step_until(h, "the dialog closed", |h| !dialog_open(h));
    let marked = format!("{part} *");
    step_until(h, "unsaved", |h| {
        let tab = tab_named(h, part);
        tab.edits.idle() && tab.unsaved() && anywhere(h, &marked)
    });
}

#[test]
fn new_names_parts_untitled_then_untitled_2_and_never_gives_a_name_again() {
    let f = fixture();
    let mut h = f.app();
    step(&mut h);
    new_part(&mut h);
    new_part(&mut h);
    let names = |h: &AppHarness| -> Vec<String> {
        h.state()
            .tabs()
            .iter()
            .map(|tab| tab.name().to_owned())
            .collect()
    };
    assert_eq!(names(&h), ["Untitled", "Untitled 2"]);
    // Untitled 2, holding no edits, closed without asking; then New: Untitled 3, the name
    // Untitled 2 had never given again in this run.
    h.get_by_label("Close Untitled 2").click();
    step_until(&mut h, "it closed", |h| h.state().tabs().len() == 1);
    assert!(!anywhere(&h, "Save changes to Untitled 2 before closing?"));
    new_part(&mut h);
    assert_eq!(names(&h), ["Untitled", "Untitled 3"]);
    step_until(&mut h, "Untitled 3 shown", |h| {
        toggled(&h.get_by_role_and_label(Role::Button, "Untitled 3")) == Some(true)
    });
    // Each a session of its own, none with a file.
    let tabs = h.state().tabs();
    assert_ne!(tabs[0].id, tabs[1].id);
    for tab in tabs {
        assert_eq!(tab.path, None);
        assert_eq!(
            f.sessions.status(&tab.id).session.unwrap().path,
            None::<String>
        );
    }
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn an_untitled_parts_edit_is_marked_and_command_s_saves_it_through_the_save_panel() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    assert!(anywhere(&h, "Untitled *"));
    // Command+S: the Save panel, named by the part; nothing written until it answers.
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 1);
    assert_eq!(
        browser.asked(),
        [Ask {
            pick: Pick::Save,
            title: "Save Untitled as".to_owned(),
            filters: vec![browse_mod::DOCUMENTS],
            folder: None,
            file_name: Some("Untitled.silico".to_owned()),
        }]
    );
    // Command+S again while it's open: no second panel, nothing sent.
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    for _ in 0..10 {
        step(&mut h);
    }
    assert_eq!(browser.asked().len(), 1);
    assert_eq!(h.state().tabs()[0].saves, 0);
    assert!(!h.state().tabs()[0].sent.contains(&Sent::Commit));
    // Picked: committed to it, the tab renamed and clean.
    let part = f.dir.path().join("part.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "renamed and clean", |h| {
        anywhere(h, "part.silico") && !anywhere(h, "part.silico *")
    });
    let tab = &h.state().tabs()[0];
    assert_eq!(tab.path.as_deref(), part.to_str());
    assert_eq!(tab.name(), "part.silico");
    assert_eq!(tab.saves, 1);
    assert!(!tab.unsaved());
    assert_eq!(tab.message, None);
    assert!(!anywhere(&h, "Untitled"));
    // The file holds the document as the session holds it: the sketch.
    let id = tab.id;
    let held = f.sessions.text(&id, None).wait().result.unwrap().text;
    assert_eq!(std::fs::read_to_string(&part).unwrap(), held);
    assert_eq!(names_in(&part), ["Sketch1"]);
    assert_eq!(
        f.sessions.status(&id).session.unwrap().path.as_deref(),
        part.to_str()
    );
    // From now on a file's: Command+S commits to it, asking nothing.
    select(&mut h, "Sketch1");
    type_name(&mut h, "x");
    step_until(&mut h, "unsaved", |h| {
        h.state().tabs()[0].edits.idle() && anywhere(h, "part.silico *")
    });
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    step_until(&mut h, "saved", |h| !anywhere(h, "part.silico *"));
    assert_eq!(names_in(&part), ["Sketch1x"]);
    assert_eq!(browser.asked().len(), 1);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn closing_an_edited_untitled_part_asks_and_dont_save_leaves_nothing_and_a_cancel_keeps_it() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    let before = listing(f.dir.path());
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    let question = "Save changes to Untitled before closing?";
    // Close: asked. Save: the Save panel, cancelled: the part stays, its edits held, and
    // nothing is said or sent.
    h.get_by_label("Close Untitled").click();
    step_until(&mut h, "the question", |h| anywhere(h, question));
    answer_question(&mut h, "Save");
    save_panel_asked(&mut h, &browser, 1);
    assert_eq!(
        browser.asked()[0].file_name.as_deref(),
        Some("Untitled.silico")
    );
    browser.answer(None);
    for _ in 0..10 {
        step(&mut h);
    }
    let tab = &h.state().tabs()[0];
    assert_eq!(h.state().tabs().len(), 1);
    assert!(tab.unsaved() && tab.transaction && !tab.closing());
    assert_eq!(tab.saves, 0);
    assert_eq!(h.state().message(), None);
    assert!(!anywhere(&h, question));
    // Close again, Don't save: closed, nothing left on disk, no panel asked.
    h.get_by_label("Close Untitled").click();
    step_until(&mut h, "the question", |h| anywhere(h, question));
    answer_question(&mut h, "Don't save");
    step_until(&mut h, "it closed", |h| h.state().tabs().is_empty());
    assert_eq!(browser.asked().len(), 1);
    assert_eq!(listing(f.dir.path()), before);
    // A quit's Save all, its panel cancelled: the quit stops, the part kept, the window
    // open, and that said.
    new_part(&mut h);
    add_sketch(&mut h, "Untitled 2");
    close_window(&mut h);
    assert!(
        window_told(&h, ViewportCommand::CancelClose),
        "a close with edits held wasn't cancelled"
    );
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    save_panel_asked(&mut h, &browser, 2);
    assert_eq!(browser.asked()[1].title, "Save Untitled 2 as");
    browser.answer(None);
    step_until(&mut h, "the quit stopped", |h| {
        h.state().message() == Some("Quit stopped: Untitled 2 wasn't closed")
    });
    for _ in 0..20 {
        step(&mut h);
        assert!(
            !window_told(&h, ViewportCommand::Close),
            "the window closed with Untitled 2's edits"
        );
    }
    let tab = &h.state().tabs()[0];
    assert_eq!(h.state().tabs().len(), 1);
    assert!(tab.unsaved() && !tab.closing());
    assert_eq!(browser.asked().len(), 2);
    assert_eq!(listing(f.dir.path()), before);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn quitting_with_two_edited_untitled_parts_saves_each_through_its_panel_in_turn() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    new_part(&mut h);
    add_sketch(&mut h, "Untitled 2");
    close_window(&mut h);
    assert!(
        window_told(&h, ViewportCommand::CancelClose),
        "a close with edits held wasn't cancelled"
    );
    step_until(&mut h, "the quit question", |h| {
        anywhere(h, "Save changes before quitting?")
            && h.query_by_label_contains("Unsaved: Untitled, Untitled 2. Quitting")
                .is_some()
    });
    answer_question(&mut h, "Save all");
    // The first's panel; the second's waits for it.
    save_panel_asked(&mut h, &browser, 1);
    assert_eq!(browser.asked()[0].title, "Save Untitled as");
    for _ in 0..10 {
        step(&mut h);
    }
    assert_eq!(browser.asked().len(), 1);
    let one = f.dir.path().join("one.silico");
    browser.answer(Some(&one));
    save_panel_asked(&mut h, &browser, 2);
    assert_eq!(browser.asked()[1].title, "Save Untitled 2 as");
    assert_eq!(
        browser.asked()[1].file_name.as_deref(),
        Some("Untitled 2.silico")
    );
    let two = f.dir.path().join("two.silico");
    browser.answer(Some(&two));
    step_until(&mut h, "the window closing", |h| {
        window_told(h, ViewportCommand::Close)
    });
    assert!(h.state().tabs().is_empty());
    for path in [&one, &two] {
        assert_eq!(names_in(path), ["Sketch1"], "{}", path.display());
    }
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn quitting_with_three_untitled_parts_stops_at_the_one_whose_panel_is_cancelled() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    for name in ["Untitled", "Untitled 2", "Untitled 3"] {
        new_part(&mut h);
        add_sketch(&mut h, name);
    }
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    save_panel_asked(&mut h, &browser, 1);
    let one = f.dir.path().join("one.silico");
    browser.answer(Some(&one));
    save_panel_asked(&mut h, &browser, 2);
    assert_eq!(browser.asked()[1].title, "Save Untitled 2 as");
    browser.answer(None);
    step_until(&mut h, "the quit stopped and the first closed", |h| {
        h.state().message() == Some("Quit stopped: Untitled 2 wasn't closed")
            && h.state().tabs().len() == 2
    });
    // The third's panel never asked: the quit stopped before it.
    for _ in 0..20 {
        step(&mut h);
        assert!(!window_told(&h, ViewportCommand::Close));
    }
    assert_eq!(browser.asked().len(), 2);
    let names: Vec<&str> = h.state().tabs().iter().map(|tab| tab.name()).collect();
    assert_eq!(names, ["Untitled 2", "Untitled 3"]);
    assert!(h.state().tabs().iter().all(|tab| tab.unsaved()));
    assert_eq!(names_in(&one), ["Sketch1"]);
    // A second quit asks again, and its Save all asks the second's panel first.
    close_window(&mut h);
    step_until(&mut h, "asked again", |h| {
        anywhere(h, "Save changes before quitting?")
            && h.query_by_label_contains("Unsaved: Untitled 2, Untitled 3. Quitting")
                .is_some()
    });
    answer_question(&mut h, "Save all");
    save_panel_asked(&mut h, &browser, 3);
    assert_eq!(browser.asked()[2].title, "Save Untitled 2 as");
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn an_untitled_parts_export_refuses_a_path_that_isnt_full_and_takes_one_that_is() {
    use silico_core::command::export::{Export, ExportFormat};
    let f = fixture();
    let documents = f.dir.path().join("Documents");
    let mut h = f.app_made(|app| app.documents_folder(Some(documents.clone())));
    step(&mut h);
    new_part(&mut h);
    add_pad(&f, &mut h, "Untitled");
    h.get_by_label("File").click();
    step(&mut h);
    step(&mut h);
    h.get_by_role_and_label(Role::Button, "Export…").click();
    step_until(&mut h, "the export dialog", |h| {
        anywhere(h, "Export Untitled")
    });
    // Its path starts in the Documents folder, named by the part.
    assert_eq!(
        path_value(&h),
        documents.join("Untitled.3mf").to_str().unwrap()
    );
    let refusal = "Give a full path: an untitled part has no folder";
    assert!(!anywhere(&h, refusal));
    press(&mut h, "STEP");
    for typed in ["out.step", "sub/out.step"] {
        retype(&mut h, In::Window, "Path", typed);
        step(&mut h);
        assert!(anywhere(&h, refusal), "{typed}");
        assert!(
            h.get_by_role_and_label(Role::Button, "Export")
                .accesskit_node()
                .is_disabled(),
            "{typed}"
        );
        press(&mut h, "Export");
        h.key_press(eframe::egui::Key::Enter);
        for _ in 0..5 {
            step(&mut h);
        }
        assert!(h.state().tabs()[0].exports.is_empty(), "{typed}");
        assert!(!f.dir.path().join(typed).exists(), "{typed}");
    }
    // A full path: taken, and written.
    let out = f.dir.path().join("out.step");
    retype(&mut h, In::Window, "Path", out.to_str().unwrap());
    step(&mut h);
    assert!(!anywhere(&h, refusal));
    press(&mut h, "Export");
    step_until(&mut h, "the dialog closed", |h| {
        !anywhere(h, "Export Untitled")
    });
    assert_eq!(
        h.state().tabs()[0].exports,
        [Export {
            format: ExportFormat::Step,
            path: out.clone(),
            replace: false,
            features: None,
        }]
    );
    assert!(out.is_file());
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn with_no_native_dialog_an_untitled_parts_save_asks_for_a_typed_full_path() {
    let f = fixture();
    // No native dialogs at all, then a panel that won't open: the typed Save As each time.
    for refusing in [None, Some(FakeBrowser::default())] {
        let mut h = match &refusing {
            None => f.app(),
            Some(browser) => {
                browser.refusing(true);
                f.app_browsing(browser)
            }
        };
        step(&mut h);
        new_part(&mut h);
        add_sketch(&mut h, "Untitled");
        h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
        step_until(&mut h, "the typed Save As", |h| {
            anywhere(h, "Save Untitled as")
        });
        if let Some(browser) = &refusing {
            // The panel was asked for first.
            assert_eq!(browser.asked().len(), 1);
            assert_eq!(browser.asked()[0].pick, Pick::Save);
        }
        // A path that isn't full: refused, said, nothing sent.
        path_field(&h).focus();
        step(&mut h);
        path_field(&h).type_text("rel.silico");
        step(&mut h);
        step(&mut h);
        let refusal = "Give a full path: an untitled part has no folder";
        assert!(anywhere(&h, refusal));
        h.key_press(eframe::egui::Key::Enter);
        for _ in 0..5 {
            step(&mut h);
        }
        assert!(anywhere(&h, "Save Untitled as"));
        assert_eq!(h.state().tabs()[0].saves, 0);
        assert!(!Path::new("rel.silico").exists());
        // A full one: saved to it.
        let made = f
            .dir
            .path()
            .join(format!("typed-{}.silico", refusing.is_some()));
        retype(&mut h, In::Window, "Path", made.to_str().unwrap());
        step(&mut h);
        assert!(!anywhere(&h, refusal));
        answer_question(&mut h, "Save");
        step_until(&mut h, "saved as it", |h| {
            h.state().tabs()[0].path.as_deref() == made.to_str() && !anywhere(h, "Save Untitled as")
        });
        step_until(&mut h, "clean", |h| !h.state().tabs()[0].unsaved());
        assert_eq!(names_in(&made), ["Sketch1"]);
        assert_eq!(never_waits::waits(), 0);
    }
}

#[test]
fn an_untitled_part_is_listed_in_recent_only_once_its_first_save_gives_it_a_file() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let file = f.recents_file();
    let mut h = f.app_made(|app| {
        app.remembering(Recents::at(file))
            .browsing(Box::new(browser.clone()))
    });
    recents_read(&mut h);
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    // Home, a while: nothing listed.
    home_button(&h).click();
    step_until(&mut h, "Home", start_shown);
    for _ in 0..20 {
        step(&mut h);
    }
    assert!(recent_names(&h).is_empty());
    assert!(
        h.state()
            .recents()
            .is_some_and(|recents| recents.list().is_empty())
    );
    // Back to it, and saved: listed.
    h.key_press(eframe::egui::Key::Escape);
    step_until(&mut h, "the part", |h| !start_shown(h));
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 1);
    let part = f.dir.path().join("part.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "saved", |h| {
        h.state().tabs()[0].path.as_deref() == part.to_str()
    });
    home_button(&h).click();
    step_until(&mut h, "listed", |h| {
        start_shown(h) && recent_names(h) == ["part.silico"]
    });
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn copy_mcp_config_with_an_untitled_part_shown_serves_the_newest_recent_ones_folder_then_documents()
{
    let f = fixture();
    let models = f.dir.path().join("models");
    std::fs::create_dir(&models).unwrap();
    let kept = models.join("b.silico");
    std::fs::write(&kept, EXAMPLE).unwrap();
    std::fs::create_dir_all(f.recents_file().parent().unwrap()).unwrap();
    std::fs::write(
        f.recents_file(),
        format!("silico recent-documents 1\n{}\n", kept.to_str().unwrap()),
    )
    .unwrap();
    let documents = f.dir.path().join("Documents");
    let file = f.recents_file();
    let mut h = f.app_made(|app| {
        app.serving_with("/opt/silico/bin/silico".to_owned())
            .documents_folder(Some(documents.clone()))
            .remembering(Recents::at(file))
    });
    recents_read(&mut h);
    new_part(&mut h);
    // The untitled part shown has no folder: the newest recent's is named.
    assert_eq!(
        h.state().mcp_config(),
        config_serving(models.to_str().unwrap())
    );
    home_button(&h).click();
    step_until(&mut h, "Home", start_shown);
    assert_eq!(
        copy_config(&mut h),
        Some(config_serving(models.to_str().unwrap()))
    );
    assert!(!anywhere(&h, silico_app::start::NO_WORKSPACE_NOTE));
    // With no recent list: the Documents folder.
    let mut bare = f.app_made(|app| {
        app.serving_with("/opt/silico/bin/silico".to_owned())
            .documents_folder(Some(documents.clone()))
    });
    step(&mut bare);
    new_part(&mut bare);
    assert_eq!(
        bare.state().mcp_config(),
        config_serving(documents.to_str().unwrap())
    );
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn quits_save_all_with_a_parts_own_save_panel_open_saves_it_once_through_that_panel() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    let before = listing(f.dir.path());
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    // Command+S: its panel open (the portal's leaves the window usable), then a quit.
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 1);
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    for _ in 0..10 {
        step(&mut h);
    }
    // No second panel: the one open saves it, and closes it.
    assert_eq!(browser.asked().len(), 1);
    let part = f.dir.path().join("part.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "the window closing", |h| {
        window_told(h, ViewportCommand::Close)
    });
    assert!(h.state().tabs().is_empty());
    assert_eq!(browser.asked().len(), 1);
    assert_eq!(names_in(&part), ["Sketch1"]);
    // One document written: the part's, and no other.
    let documents = |listed: Vec<String>| -> Vec<String> {
        listed
            .into_iter()
            .filter(|name| name.ends_with(".silico"))
            .collect()
    };
    assert!(documents(before).is_empty());
    assert_eq!(documents(listing(f.dir.path())), ["part.silico"]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn quits_save_all_while_a_parts_save_as_runs_waits_for_it_and_asks_no_panel() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    new_part(&mut h);
    // Its pad, which the held check builds again.
    add_pad(&f, &mut h, "Untitled");
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 1);
    // Picked, its Save As held behind the session's queue.
    let (hold, check) = hold_queue(&f, &h, 0);
    let part = f.dir.path().join("part.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "the Save As sent", |h| {
        h.state().tabs()[0].saving_as()
    });
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    for _ in 0..20 {
        step(&mut h);
    }
    assert_eq!(browser.asked().len(), 1);
    assert!(!window_told(&h, ViewportCommand::Close));
    hold.release();
    let _ = check.wait();
    step_until(&mut h, "the window closing", |h| {
        window_told(h, ViewportCommand::Close)
    });
    assert!(h.state().tabs().is_empty());
    assert_eq!(browser.asked().len(), 1);
    assert_eq!(names_in(&part), ["Sketch1", "Pad"]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn a_stopped_quit_leaves_a_save_panel_it_marked_to_save_without_closing() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    // A document whose save will be a conflict, and an untitled part with its panel open.
    let theirs_path = f.file("a.silico", EXAMPLE);
    h.state_mut().open(theirs_path.to_str().unwrap(), false);
    step_until(&mut h, "its features", |h| {
        h.query_by_role_and_label(Role::Pane, "Timeline").is_some() && shows(h, "Timeline", "Pin")
    });
    select(&mut h, "Pin");
    type_name(&mut h, "Q");
    step_until(&mut h, "unsaved", |h| anywhere(h, "a.silico *"));
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 1);
    let theirs = EXAMPLE.replace(r#""name": "Hole""#, r#""name": "Theirs""#);
    std::fs::write(&theirs_path, &theirs).unwrap();
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    step_until(&mut h, "the quit stopped", |h| {
        h.state().message() == Some("Quit stopped: a.silico wasn't closed")
    });
    // The pick now saves the part, and leaves it open.
    let part = f.dir.path().join("part.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "saved", |h| {
        h.state()
            .tabs()
            .iter()
            .any(|tab| tab.path.as_deref() == part.to_str() && !tab.unsaved())
    });
    for _ in 0..20 {
        step(&mut h);
        assert!(!window_told(&h, ViewportCommand::Close));
    }
    assert_eq!(h.state().tabs().len(), 2);
    assert!(h.state().tabs().iter().all(|tab| !tab.closing()));
    assert_eq!(names_in(&part), ["Sketch1"]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn with_no_native_dialogs_close_and_quit_save_an_untitled_part_through_the_typed_save_as() {
    let f = fixture();
    let mut h = f.app();
    step(&mut h);
    new_part(&mut h);
    add_sketch(&mut h, "Untitled");
    new_part(&mut h);
    add_sketch(&mut h, "Untitled 2");
    // Close's Save: the typed Save As, a full path, saved and closed.
    h.get_by_label("Untitled *").click();
    step(&mut h);
    h.get_by_label("Close Untitled").click();
    step_until(&mut h, "the close question", |h| {
        anywhere(h, "Save changes to Untitled before closing?")
    });
    answer_question(&mut h, "Save");
    step_until(&mut h, "the typed Save As", |h| {
        anywhere(h, "Save Untitled as")
    });
    let one = f.dir.path().join("one.silico");
    type_path(&mut h, &one);
    answer_question(&mut h, "Save");
    step_until(&mut h, "saved and closed", |h| {
        h.state().tabs().len() == 1 && h.state().tabs()[0].name() == "Untitled 2"
    });
    assert_eq!(names_in(&one), ["Sketch1"]);
    // Quit's Save all, its typed Save As cancelled: the quit stops, the part kept.
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    step_until(&mut h, "the typed Save As", |h| {
        anywhere(h, "Save Untitled 2 as")
    });
    answer_question(&mut h, "Cancel");
    step_until(&mut h, "the quit stopped", |h| {
        h.state().message() == Some("Quit stopped: Untitled 2 wasn't closed")
    });
    for _ in 0..20 {
        step(&mut h);
        assert!(!window_told(&h, ViewportCommand::Close));
    }
    assert!(h.state().tabs()[0].unsaved());
    // Quit again, Save all, a path to a file there, and Replace: saved over it and closed,
    // and the window with it.
    let there = f.file("there.silico", "an older copy");
    close_window(&mut h);
    step_until(&mut h, "the quit question", |h| {
        h.query_by_label_contains("Save changes before quitting?")
            .is_some()
    });
    answer_question(&mut h, "Save all");
    step_until(&mut h, "the typed Save As", |h| {
        anywhere(h, "Save Untitled 2 as")
    });
    type_path(&mut h, &there);
    answer_question(&mut h, "Save");
    let asked = format!("{} already exists. Replace it?", there.to_str().unwrap());
    step_until(&mut h, "the Replace question", |h| anywhere(h, &asked));
    answer_question(&mut h, "Replace");
    step_until(&mut h, "the window closing", |h| {
        window_told(h, ViewportCommand::Close)
    });
    assert!(h.state().tabs().is_empty());
    assert_eq!(names_in(&there), ["Sketch1"]);
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn an_untitled_parts_save_is_on_with_no_edits_and_asks_the_panel() {
    let f = fixture();
    let browser = FakeBrowser::default();
    let mut h = f.app_browsing(&browser);
    step(&mut h);
    new_part(&mut h);
    step(&mut h);
    assert!(!h.state().tabs()[0].unsaved());
    let save = || {
        h.query_all_by_role_and_label(Role::Button, "Save")
            .next()
            .unwrap()
            .accesskit_node()
            .is_disabled()
    };
    assert!(!save(), "Save off on an untitled part");
    // The app bar's Save: the panel; cancelled, then Command+S: the panel again.
    h.query_all_by_role_and_label(Role::Button, "Save")
        .next()
        .unwrap()
        .click_accesskit();
    save_panel_asked(&mut h, &browser, 1);
    browser.answer(None);
    for _ in 0..5 {
        step(&mut h);
    }
    h.key_press_modifiers(eframe::egui::Modifiers::COMMAND, eframe::egui::Key::S);
    save_panel_asked(&mut h, &browser, 2);
    let part = f.dir.path().join("empty.silico");
    browser.answer(Some(&part));
    step_until(&mut h, "saved", |h| {
        h.state().tabs()[0].path.as_deref() == part.to_str()
    });
    // The empty document, as the session holds it.
    let id = h.state().tabs()[0].id;
    let held = f.sessions.text(&id, None).wait().result.unwrap().text;
    assert_eq!(std::fs::read_to_string(&part).unwrap(), held);
    assert!(names_in(&part).is_empty());
    // A file's now, with no edits: Save off.
    step_until(&mut h, "Save off", |h| {
        h.query_all_by_role_and_label(Role::Button, "Save")
            .next()
            .unwrap()
            .accesskit_node()
            .is_disabled()
    });
    assert_eq!(never_waits::waits(), 0);
}

