#[test]
fn made_by_selects_its_feature_edit_opens_its_dialog_and_fillet_starts_with_the_edge() {
    let f = fixture();
    let mut h = a_measured_box(&f);
    let block = silico_core::document::FeatureId::new("k7f2qx3m").unwrap();
    // Made by: Block, a link that selects it. Each click waits for its card's measures: the
    // face's read, landing, adds a row (Normal) and a button (Sketch on this face) and
    // moves what's below them, so a click aimed before it lands can miss.
    select_in_box(&mut h, &["Face6"]);
    row_until(&mut h, "Area", "800.00 mm²");
    row_until(&mut h, "Made by", "Block");
    h.get_by_role_and_label(Role::Pane, "Properties")
        .get_by_role_and_label(Role::Link, "Block")
        .click();
    step_until(&mut h, "Block selected", |h| {
        h.state().tabs()[0].selection().feature() == Some(&block)
    });
    // Edit Block: the box's dialog, as Edit Feature opens it.
    select_in_box(&mut h, &["Face6"]);
    row_until(&mut h, "Area", "800.00 mm²");
    h.get_by_role_and_label(Role::Pane, "Properties")
        .get_by_role_and_label(Role::Button, "Edit Block")
        .click();
    step_until(&mut h, "Block's dialog", |h| {
        h.state().tabs()[0].dialog.as_ref().is_some_and(|dialog| {
            dialog.kind == silico_app::dialog::Kind::Box && dialog.feature.as_ref() == Some(&block)
        })
    });
    h.state_mut().tabs_mut()[0].close_dialog(&f.sessions, false);
    step_until(&mut h, "the dialog closed", |h| {
        !h.state().tabs()[0].in_dialog()
    });
    // Fillet, with Edge12 selected: the fillet's dialog, its edges box holding Edge12, as the
    // toolbar's Fillet takes the selection.
    select_in_box(&mut h, &["Edge12"]);
    row_until(&mut h, "Length", "40.00 mm");
    h.get_by_role_and_label(Role::Pane, "Properties")
        .get_by_role_and_label(Role::Button, "Fillet")
        .click();
    step_until(&mut h, "the fillet's dialog with Edge12", |h| {
        h.state().tabs()[0].dialog.as_ref().is_some_and(|dialog| {
            dialog.kind == silico_app::dialog::Kind::Fillet
                && dialog
                    .names()
                    .is_some_and(|names| names.names == ["k7f2qx3m.box.Edge12"])
        })
    });
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn two_faces_show_their_distance_normal_distance_and_angle_and_a_pair_angle_refuses_no_angle() {
    let f = fixture();
    let mut h = a_measured_box(&f);
    // The bottom and the top: 10 apart (the block's height), each way, facing apart: the
    // core's wedge of two faces facing apart is 0, parallel.
    select_in_box(&mut h, &["Face5", "Face6"]);
    row_until(&mut h, "Distance", "10.00 mm");
    row_until(&mut h, "Angle", "0° (parallel)");
    assert_eq!(
        row_value(&h, "Normal distance").as_deref(),
        Some("10.00 mm")
    );
    assert!(shows(&h, "Properties", "2 selected"));
    assert!(shows(&h, "Properties", "2 faces"));
    assert!(shows(&h, "Properties", "MEASURE"));
    // Above SELECTION.
    let top = |h: &AppHarness, label: &str| {
        h.get_by_role_and_label(Role::Pane, "Properties")
            .get_by_label(label)
            .rect()
            .top()
    };
    assert!(top(&h, "MEASURE") < top(&h, "SELECTION"));
    // The x = 0 face and the bottom: they meet, at 90°, so no normal distance.
    select_in_box(&mut h, &["Face1", "Face5"]);
    row_until(&mut h, "Angle", "90.00°");
    assert_eq!(row_value(&h, "Distance").as_deref(), Some("0.00 mm"));
    assert_eq!(row_value(&h, "Normal distance"), None);
    // The top and Vertex1: `angle` refuses a vertex, so there's no Angle row and nothing said
    // of it; the vertex is its own centre, 10 from the face.
    select_in_box(&mut h, &["Face6", "Vertex1"]);
    row_until(&mut h, "Distance", "10.00 mm");
    row_until(&mut h, "Center to element", "10.00 mm");
    for _ in 0..5 {
        step(&mut h);
    }
    assert_eq!(row_value(&h, "Angle"), None);
    assert!(!shows(&h, "Properties", "invalid_input"));
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn a_measure_waited_for_shows_no_value_of_the_selection_before_it_and_one_answered_late_none() {
    // Held deterministically by the fake: the distance between the x = 0 face and the bottom.
    let f = fixture();
    let mut h = a_measured_box(&f);
    let between_1_and_5 = |op: &silico_core::kernel::Op| {
        matches!(
            op,
            silico_core::kernel::Op::Distance { first, second, .. }
                if (first.index, second.index) == (1, 5)
        )
    };
    select_in_box(&mut h, &["Face5", "Face6"]);
    row_until(&mut h, "Distance", "10.00 mm");
    let hold = f.kernel.hold(between_1_and_5);
    select_in_box(&mut h, &["Face1", "Face5"]);
    // Its angle answers (it asks no kernel), its distance doesn't: never the last pair's.
    row_until(&mut h, "Angle", "90.00°");
    for _ in 0..10 {
        step(&mut h);
        assert_eq!(
            row_value(&h, "Distance").as_deref(),
            Some("Not measured yet")
        );
        assert_eq!(row_value(&h, "Normal distance"), None);
    }
    hold.release();
    row_until(&mut h, "Distance", "0.00 mm");
    // Held again, and the selection changed before it answers: the pair after it is shown,
    // and the held one's answer, once let go, is never shown for it.
    let hold = f.kernel.hold(between_1_and_5);
    select_in_box(&mut h, &["Face6"]);
    select_in_box(&mut h, &["Face1", "Face5"]);
    step(&mut h);
    select_in_box(&mut h, &["Face6", "Vertex1"]);
    row_until(&mut h, "Distance", "10.00 mm");
    hold.release();
    for _ in 0..10 {
        step(&mut h);
        std::thread::sleep(Duration::from_millis(5));
        assert_eq!(row_value(&h, "Distance").as_deref(), Some("10.00 mm"));
    }
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn a_pair_waiting_on_a_feature_that_failed_says_why_and_not_that_its_not_measured_yet() {
    // The block made 41 long fails to build: its two faces selected wait, each with why,
    // which the Measure section says in place of its rows, as one element's Stability says
    // it.
    let f = fixture();
    f.kernel.refuse(|op| match op {
        Op::MakePrimitive(Primitive::Box { dx, .. }) if *dx == 41.0 => {
            Some(Error::new(ErrorCode::KernelFailed, "the block came apart"))
        }
        _ => None,
    });
    let mut h = a_measured_box(&f);
    select_in_box(&mut h, &["Face5", "Face6"]);
    row_until(&mut h, "Distance", "10.00 mm");
    set_through_the_core(&f, &mut h, "k7f2qx3m", "length", "41");
    let whys: Vec<String> = element_states(&h)
        .into_iter()
        .map(|(name, why)| why.unwrap_or_else(|| panic!("{name} isn't waiting")))
        .collect();
    // Each in the core's words, naming its element and its place in the selection.
    for (at, why) in whys.iter().enumerate() {
        assert!(why.starts_with(&format!("selection.{at}, ")), "{why}");
        assert!(why.contains("the block came apart"), "{why}");
    }
    let said = |h: &AppHarness, why: &str| {
        h.get_by_role_and_label(Role::Pane, "Properties")
            .query_all_by_label_contains(why)
            .count()
    };
    step_until(&mut h, "why each waits said", |h| {
        whys.iter().all(|why| said(h, why) > 0)
    });
    for _ in 0..5 {
        step(&mut h);
    }
    // Each said once, in place of the rows, and never as a measure not read yet.
    for why in &whys {
        assert_eq!(said(&h, why), 1, "{why}");
    }
    assert!(!shows(&h, "Properties", "Not measured yet"));
    assert_eq!(row_value(&h, "Distance"), None);
    assert_eq!(row_value(&h, "Angle"), None);
    // Each on a warning's card (`.err-card.warn`: `--alert-warn-bg`, rgba(223, 119, 0, .18),
    // bordered #5c3a08), as one element's Stability card says it: the pair waits, it isn't
    // in error.
    let warn = eframe::egui::Color32::from_rgba_unmultiplied(223, 119, 0, 46);
    let warn_border = eframe::egui::Color32::from_rgb(0x5c, 0x3a, 0x08);
    for why in &whys {
        let at = h
            .get_by_role_and_label(Role::Pane, "Properties")
            .query_all_by_label_contains(why)
            .next()
            .unwrap()
            .rect();
        let cards: Vec<_> = shapes_painted(&h)
            .into_iter()
            .filter_map(|shape| match shape {
                eframe::egui::Shape::Rect(card) if card.rect.contains_rect(at) => {
                    Some((card.fill, card.stroke.color))
                }
                _ => None,
            })
            .collect();
        assert!(cards.contains(&(warn, warn_border)), "{why}: {cards:?}");
    }
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn one_element_waiting_on_a_feature_that_failed_says_so_in_its_measures_never_not_measured_yet() {
    // #414's second review: the block made 41 long fails to build. Its top, selected, waits
    // with why, which its Stability card says; its Area says it isn't measured because its
    // feature didn't build, never "not measured yet", for as long as the block fails. Built
    // 40 long again, it's measured again.
    let f = fixture();
    f.kernel.refuse(|op| match op {
        Op::MakePrimitive(Primitive::Box { dx, .. }) if *dx == 41.0 => {
            Some(Error::new(ErrorCode::KernelFailed, "the block came apart"))
        }
        _ => None,
    });
    let mut h = a_measured_box(&f);
    select_in_box(&mut h, &["Face6"]);
    row_until(&mut h, "Area", "800.00 mm²");
    set_through_the_core(&f, &mut h, "k7f2qx3m", "length", "41");
    let not_built = "Not measured: its feature didn't build";
    row_until(&mut h, "Area", not_built);
    for _ in 0..5 {
        step(&mut h);
        assert_eq!(row_value(&h, "Area").as_deref(), Some(not_built));
    }
    assert!(!shows(&h, "Properties", "Not measured yet"));
    assert_eq!(row_value(&h, "Normal"), None);
    // Why, in the core's words, said once: by its Stability card.
    let states = element_states(&h);
    let [(_, Some(why))] = states.as_slice() else {
        panic!("Face6 isn't waiting alone: {states:?}");
    };
    assert!(why.contains("the block came apart"), "{why}");
    assert_eq!(row_value(&h, "Stability").as_deref(), Some("Waiting"));
    assert_eq!(
        h.get_by_role_and_label(Role::Pane, "Properties")
            .query_all_by_label_contains(why)
            .count(),
        1
    );
    set_through_the_core(&f, &mut h, "k7f2qx3m", "length", "40");
    row_until(&mut h, "Area", "800.00 mm²");
    assert_eq!(never_waits::waits(), 0);
}

#[test]
fn sketch_on_this_face_creates_a_sketch_on_the_picked_face() {
    // The block's top selected, a plane facing +z: Sketch on this face adds an empty sketch
    // on it, by the name a store writes for it (its own, stable), its x +x (the attacher's
    // default for a normal along z, filled in by the core), and opens sketch mode on it.
    // Cancel leaves the document as it was. (Off while sketch mode can't open: the property
    // panel's own test; off for an unstable face: the test after this.)
    let f = fixture();
    let mut h = a_measured_box(&f);
    select_in_box(&mut h, &["Face6"]);
    row_until(&mut h, "Area", "800.00 mm²");
    h.get_by_role_and_label(Role::Pane, "Properties")
        .get_by_role_and_label(Role::Button, "Sketch on this face")
        .click();
    step_until(&mut h, "its sketch added", |h| {
        sketch_mode(h).is_some_and(|mode| mode.sketch.is_some())
    });
    settled(&mut h);
    assert_eq!(
        fields_of(&text_of(&f.sessions, &h), "Sketch1"),
        Some(empty_sketch(
            "Sketch1",
            r#"{"face": "k7f2qx3m.box.Face6", "x": "+x", "reversed": false}"#
        ))
    );
    sketch_read(&mut h);
    assert!(sketch_mode(&h).unwrap().plane_problem().is_none());
    leave_sketch(&mut h, false);
    assert_eq!(text_of(&f.sessions, &h), A_BOX);
    assert_eq!(never_waits::waits(), 0);
}

/// `document` opened as `file`, its Block (k7f2qx3m) described and measured as a real box;
/// the Block's top, Face6, sketched on by Sketch on this face, a rectangle drawn inside it
/// (the face's frame has its origin at (0, 0, 10) and its x +x, so the face spans 0 to 40
/// by 0 to 20), and the sketch finished and listed in the browser as `name`. The harness,
/// and the sketch's ID.
fn a_rectangle_on_the_blocks_top(
    f: &Fixture,
    file: &str,
    document: &str,
    name: &str,
) -> (AppHarness, silico_core::document::FeatureId) {
    use silico_app::sketch::tools::Choice;
    use silico_core::sketch_tools::ToolKind;
    describes_a_real_box(f);
    measures_the_box(f);
    let (mut h, _) = f.opened(file, document);
    step_until(&mut h, "the model published", |h| {
        h.state().tabs()[0].published.is_some()
    });
    step(&mut h);
    select_in_box(&mut h, &["Face6"]);
    row_until(&mut h, "Area", "800.00 mm²");
    h.get_by_role_and_label(Role::Pane, "Properties")
        .get_by_role_and_label(Role::Button, "Sketch on this face")
        .click();
    step_until(&mut h, "its sketch added", |h| {
        sketch_mode(h).is_some_and(|mode| mode.sketch.is_some())
    });
    sketch_read(&mut h);
    let sketch = sketch_mode(&h).unwrap().sketch.clone().unwrap();
    // R, the corner rectangle, then its two corners clicked.
    h.key_press(eframe::egui::Key::R);
    step(&mut h);
    assert_eq!(
        sketch_mode(&h).unwrap().tools.choice(),
        Some(Choice::Draw(ToolKind::CornerRectangle))
    );
    sketch_events(f, &mut h, &clicked(10.0, 5.0));
    sketch_events(f, &mut h, &clicked(30.0, 15.0));
    settled(&mut h);
    read_with_lines(&mut h, 4);
    assert_rectangle_in(
        &sketch_of_text(f, &h, sketch.as_str()),
        [10.0, 5.0],
        [30.0, 15.0],
    );
    leave_sketch(&mut h, true);
    step_until(&mut h, "its sketch listed", |h| shows(h, "Browser", name));
    (h, sketch)
}

/// The sketch `name` chosen in the browser, and a `kind` (a sweep) made from it: CREATE's
/// button on, its dialog open, and its add answered and settled.
fn a_sweep_from(h: &mut AppHarness, name: &str, kind: &str) {
    h.get_by_role_and_label(Role::Pane, "Browser")
        .get_by_label(name)
        .click();
    step(h);
    assert!(
        !h.get_by_role_and_label(Role::Toolbar, "CREATE")
            .get_by_label(kind)
            .accesskit_node()
            .is_disabled(),
        "{kind} is on"
    );
    create(h, kind);
    added(h);
    settled(h);
}

/// A Pocket's or a Pad's fields, as `fields_of` gives them: on `base`, from `sketch`, with
/// its dialog's default extent.
fn sweep_fields(kind: &str, base: &str, sketch: &str) -> Vec<(String, Plain)> {
    let length = if kind == "Pocket" { 5 } else { 10 };
    expected(&format!(
        r#"{{"type": "{}", "name": "{kind}", "base": "{base}", "sketch": "{sketch}", "extent": {{"type": "one_side", "length": {length}, "reversed": false}}}}"#,
        kind.to_lowercase()
    ))
}

#[test]
fn a_sketch_on_a_face_consumes_nothing_so_a_pocket_or_pad_from_it_takes_that_body() {
    // The block's top, Face6, sketched on. The sketch names the block as the feature its face
    // is on, but the gate counts a feature's base and tool alone as consuming a solid, and a
    // sketch has neither: the block is still a body a sweep can build on. So Pocket is on in
    // CREATE, and a Pocket's, or a Pad's, add takes the block, its face's body, as its base.
    for kind in ["Pocket", "Pad"] {
        let f = fixture();
        let (mut h, sketch) = a_rectangle_on_the_blocks_top(&f, "box.silico", A_BOX, "Sketch1");
        a_sweep_from(&mut h, "Sketch1", kind);
        assert_eq!(
            fields_of(&text_of(&f.sessions, &h), kind),
            Some(sweep_fields(kind, "k7f2qx3m", sketch.as_str())),
            "{kind}"
        );
        assert_eq!(never_waits::waits(), 0);
    }
}

/// The M2.1 example's Block and Pin ([`EXAMPLE`]) before its Hole: two bodies, standing
/// apart, the Pin built last.
const BLOCK_AND_PIN: &str = r#"{
  "silico": 1,
  "units": {"length": "mm", "resolution": "1nm"},
  "naming": 5,
  "features": [
    {"id": "k7f2qx3m", "type": "box", "v": 1, "name": "Block", "position": [0, 0, 0], "length": 40, "width": 20, "height": 10},
    {"id": "a91cw0de", "type": "cylinder", "v": 1, "name": "Pin", "position": [20, 10, -1], "radius": 2.5, "height": 12}
  ]
}
"#;

#[test]
fn a_pocket_or_pad_from_a_sketch_on_the_first_bodys_face_builds_on_that_body_not_the_last() {
    // #438's review, L1: a Block, then a separate Pin, the tip (the last body built, nothing
    // consuming it). The Block's top sketched on. A sweep from a sketch on a face builds on
    // that face's body, as SolidWorks merges it and FreeCAD's PartDesign builds in the
    // sketch's own Body: a Pocket's add, or a Pad's, names the Block as its base, never the
    // Pin.
    for kind in ["Pocket", "Pad"] {
        let f = fixture();
        let (mut h, sketch) =
            a_rectangle_on_the_blocks_top(&f, "block-and-pin.silico", BLOCK_AND_PIN, "Sketch1");
        a_sweep_from(&mut h, "Sketch1", kind);
        assert_eq!(
            fields_of(&text_of(&f.sessions, &h), kind),
            Some(sweep_fields(kind, "k7f2qx3m", sketch.as_str())),
            "{kind}"
        );
        assert_eq!(never_waits::waits(), 0);
    }
}

/// [`BLOCK_AND_PIN`], and Loose, a closed square on xy from (18, 8) to (22, 12) about the
/// Pin's axis, nothing built from it.
const BLOCK_PIN_AND_LOOSE: &str = r#"{
  "silico": 1,
  "units": {"length": "mm", "resolution": "1nm"},
  "naming": 5,
  "features": [
    {"id": "k7f2qx3m", "type": "box", "v": 1, "name": "Block", "position": [0, 0, 0], "length": 40, "width": 20, "height": 10},
    {"id": "a91cw0de", "type": "cylinder", "v": 1, "name": "Pin", "position": [20, 10, -1], "radius": 2.5, "height": 12},
    {"id": "s0000009", "type": "sketch", "v": 1, "name": "Loose", "plane": "xy", "points": [{"id": "pa000000", "x": 18, "y": 8, "construction": false}, {"id": "pb000000", "x": 22, "y": 8, "construction": false}, {"id": "pc000000", "x": 22, "y": 12, "construction": false}, {"id": "pd000000", "x": 18, "y": 12, "construction": false}], "lines": [{"id": "na000000", "from": "pa000000", "to": "pb000000", "construction": false}, {"id": "nb000000", "from": "pb000000", "to": "pc000000", "construction": false}, {"id": "nc000000", "from": "pc000000", "to": "pd000000", "construction": false}, {"id": "nd000000", "from": "pd000000", "to": "pa000000", "construction": false}], "circles": [], "arcs": [], "constraints": []}
  ]
}
"#;

/// Over [`BLOCK_PIN_AND_LOOSE`], with Sketch2 drawn on the Block's top: a Pocket's dialog
/// opened on `first`, its add answered with `first_base`; then each of `then` picked into its
/// box in turn, a sketch and the base it should take, the pocket's fields checked once each
/// edit is answered; and again once OK keeps the last.
fn sketches_picked_after_the_add(first: &str, first_base: &str, then: &[(&str, &str)]) {
    let f = fixture();
    let (mut h, drawn) =
        a_rectangle_on_the_blocks_top(&f, "loose.silico", BLOCK_PIN_AND_LOOSE, "Sketch2");
    let id = |name: &str| {
        if name == "Loose" {
            "s0000009".to_owned()
        } else {
            drawn.as_str().to_owned()
        }
    };
    a_sweep_from(&mut h, first, "Pocket");
    assert_eq!(
        fields_of(&text_of(&f.sessions, &h), "Pocket"),
        Some(sweep_fields("Pocket", first_base, &id(first)))
    );
    let mut want = None;
    for (sketch, base) in then {
        h.get_by_role_and_label(Role::Pane, "Browser")
            .get_by_label(sketch)
            .click();
        let picked = id(sketch);
        step_until(&mut h, "the sketch picked sent", |h| {
            fields_of(&text_of(&f.sessions, h), "Pocket").is_some_and(|fields| {
                fields
                    .iter()
                    .any(|(key, value)| key == "sketch" && *value == Plain::String(picked.clone()))
            })
        });
        settled(&mut h);
        want = Some(sweep_fields("Pocket", base, &picked));
        assert_eq!(
            fields_of(&text_of(&f.sessions, &h), "Pocket"),
            want,
            "{sketch}"
        );
    }
    h.key_press(eframe::egui::Key::Enter);
    step_until(&mut h, "the dialog closed", |h| !dialog_open(h));
    settled(&mut h);
    assert_eq!(fields_of(&text_of(&f.sessions, &h), "Pocket"), want);
    assert_eq!(never_waits::waits(), 0);
}

/// [`sketches_picked_after_the_add`] of one sketch picked after the add.
fn a_sketch_picked_after_the_add(first: &str, first_base: &str, then: &str, then_base: &str) {
    sketches_picked_after_the_add(first, first_base, &[(then, then_base)]);
}

